import React from "react";
import logo from "../assests/vighnexlogo.png";

const Icon = ({ type, size = 24 }) => {
  const paths = {
    code: (
      <>
        <path d="M9 18 3 12l6-6" />
        <path d="m15 6 6 6-6 6" />
        <path d="m14 4-4 16" />
      </>
    ),
    design: (
      <>
        <rect x="3" y="3" width="18" height="18" rx="3" />
        <path d="M8 8h8M8 12h5M8 16h8" />
      </>
    ),
    marketing: (
      <>
        <path d="M3 11v2M6 9v6M9 7v10M12 5v14M15 8v8M18 10v4M21 12h.01" />
      </>
    ),
    mobile: (
      <>
        <rect x="6" y="2" width="12" height="20" rx="3" />
        <path d="M10 18h4" />
      </>
    ),
    cloud: (
      <path d="M17.5 19H9a6 6 0 1 1 1.3-11.86A7 7 0 0 1 23 12a4 4 0 0 1-5.5 7Z" />
    ),
    shield: (
      <>
        <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z" />
        <path d="m9 12 2 2 4-5" />
      </>
    ),
    rocket: (
      <>
        <path d="M4.5 16.5c-1.5 1.5-2 4-2 4s2.5-.5 4-2l2-2-2-2-2 2Z" />
        <path d="m14 5 5 5" />
        <path d="M13 4c3-2 7-2 8-1-1 1 0 5-1 7l-7 7-5-5 7-8Z" />
        <circle cx="16" cy="8" r="1" />
      </>
    ),
    target: (
      <>
        <circle cx="12" cy="12" r="9" />
        <circle cx="12" cy="12" r="5" />
        <circle cx="12" cy="12" r="1" />
      </>
    ),
    users: (
      <>
        <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" />
        <circle cx="9" cy="7" r="4" />
        <path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75" />
      </>
    ),
    arrow: (
      <>
        <path d="M5 12h14" />
        <path d="m13 6 6 6-6 6" />
      </>
    ),
    star: (
      <path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9L12 3Z" />
    ),
    phone: (
      <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.78.62 2.63a2 2 0 0 1-.45 2.11L8 9.73a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.85.29 1.73.5 2.63.62A2 2 0 0 1 22 16.92Z" />
    ),
    mail: (
      <>
        <rect x="3" y="5" width="18" height="14" rx="2" />
        <path d="m3 7 9 6 9-6" />
      </>
    ),
    location: (
      <>
        <path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z" />
        <circle cx="12" cy="10" r="2.5" />
      </>
    ),
    menu: <path d="M4 6h16M4 12h16M4 18h16" />,
    close: (
      <>
        <path d="M6 6l12 12" />
        <path d="M18 6 6 18" />
      </>
    ),
    spark: (
      <>
        <path d="m12 3 1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5L12 3Z" />
        <path d="m19 16 .7 2.3L22 19l-2.3.7L19 22l-.7-2.3L16 19l2.3-.7L19 16Z" />
      </>
    ),
    database: (
      <>
        <ellipse cx="12" cy="5" rx="8" ry="3" />
        <path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5" />
        <path d="M4 12v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7" />
      </>
    ),
    layers: (
      <>
        <path d="m12 2 9 5-9 5-9-5 9-5Z" />
        <path d="m3 12 9 5 9-5" />
        <path d="m3 17 9 5 9-5" />
      </>
    ),
  };

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {paths[type] || paths.spark}
    </svg>
  );
};

export { Icon };

export default function Header({
  menuOpen,
  setMenuOpen,
  scrolled,
  scrollTo,
}) {
  const container = {
    width: "min(1180px,92%)",
    margin: "0 auto",
  };

  const button = {
    border: 0,
    borderRadius: 50,
    padding: "14px 23px",
    fontSize: 14,
    fontWeight: 800,
    cursor: "pointer",
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    gap: 9,
    textDecoration: "none",
  };

  return (
    <nav
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        height: 78,
        zIndex: 1000,
        display: "flex",
        alignItems: "center",
        background: "rgba(250,247,240,.94)",
        backdropFilter: "blur(14px)",
        boxShadow: scrolled ? "0 8px 30px rgba(0,0,0,.09)" : "none",
      }}
    >
      <div
        style={{
          ...container,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 25,
        }}
      >
        <div
          onClick={() => scrollTo("home")}
          style={{
            display: "flex",
            alignItems: "center",
            cursor: "pointer",
            minWidth: 190,
          }}
        >
          <img
            src={logo}
            alt="Vighnex Technologies"
            style={{
              width: 185,
              height: 58,
              objectFit: "contain",
              objectPosition: "left center",
              display: "block",
            }}
          />
        </div>

        <div
          style={{
            display: menuOpen ? "flex" : "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 20,
            flexWrap: "wrap",
            flex: 1,
          }}
        >
          {[
            ["home", "Home"],
            ["about", "About"],
            ["services", "Services"],
            ["why", "Why Us"],
            ["technology", "Technology"],
            ["process", "Process"],
            ["projects", "Projects"],
            ["testimonials", "Testimonials"],
            ["faq", "FAQ"],
            ["contact", "Contact"],
          ].map(([id, text]) => (
            <button
              key={id}
              onClick={() => scrollTo(id)}
              style={{
                border: 0,
                background: "transparent",
                color: "#24384b",
                fontWeight: 700,
                fontSize: 13,
                cursor: "pointer",
                padding: "6px 2px",
              }}
            >
              {text}
            </button>
          ))}
        </div>

        <button
          onClick={() => scrollTo("contact")}
          style={{
            ...button,
            background: "#092338",
            color: "#fff",
            whiteSpace: "nowrap",
          }}
        >
          Let's Connect <Icon type="arrow" size={16} />
        </button>

        <button
          onClick={() => setMenuOpen(!menuOpen)}
          style={{
            border: 0,
            background: "transparent",
            color: "#092338",
            cursor: "pointer",
            display: "none",
          }}
        >
          <Icon type={menuOpen ? "close" : "menu"} size={28} />
        </button>
      </div>
    </nav>
  );
}
